        '“죽은 뿌리 껍질을 파먹는 갑충 군락은 개체의 죽음을 세지 않고 오직 살아남은 외피만 대물림한다.”': '“啃食枯死根皮的甲虫群落不计个体的死亡，只把存活下来的外壳代代相传。”',
        '“열 번의 범람을 막아낸 방벽 위에는 벌레의 체액 대신 꺾이지 않는 살의가 굳어 붙었다.”': '“在挡下十次泛滥的壁垒上，凝固的不是虫子的体液，而是不屈的杀意。”',
