        '레벨 200 달성': '达到 200 级',
        '“필멸의 한계를 넘어 두 번째 백(百)의 고리에 도달한 기록.”': '“跨越必死之限，抵达第二个百之环的记录。”',
        '“비대해진 영혼의 무게를 이기지 못해 주변의 나이테가 스스로 길을 비킨다.”': '“周围的年轮承受不住膨胀灵魂的重量，自行让开了路。”',
