        '최종 관문 보스를 생명력 피해 없이 처치': '未受生命伤害击杀最终关卡首领',
        '“단 한 방울의 피도 흘리지 않고 정점의 포식자를 베어 넘겼다.”': '“未流一滴血，便斩倒了顶点的掠食者。”',
