        '“제3호 시제품: 결코 부러지지 않는 두께를 지녔으나, 아무것도 베지 못하는 쇳덩이에 불과함. 폐기한다.”': '“第 3 号试制品：拥有绝不断裂的厚度，却不过是什么也砍不动的铁块。废弃。”',
