        '“제5호 시제품: 허공을 가르는 그림자처럼 부딪힘을 피하나, 나무껍질의 저항 앞에서는 미끄러질 뿐임. 폐기한다.”': '“第 5 号试制品：如划破虚空的影子般躲避碰撞，但在树皮的阻力面前只会打滑。废弃。”',
