        '그루터기 함에서 비활성화된 그루터기 아이템 하나마다 생명력 +5%, 방어도 +25(최대 4개).': '树桩匣中每个被停用的树桩物品使生命 +5%、护甲 +25（最多4个）。',
        '맞닿은 그루터기 아이템 하나마다 물리 피해 +7%, 생명력 −2%.': '每个相邻树桩物品使物理伤害 +7%，生命 −2%。',
