        '생명력이 일정 % 이하인 보스가 아닌 적을 즉시 처치합니다.': '立即击杀生命不高于一定百分比的非Boss敌人。',
        '리바이어던의 권능': '利维坦的权能',
        '보스 처치 피해를 가장 높게 보장하는 최상위 전용 옵션입니다.': '保证最高Boss击杀伤害的顶级专属词缀。',
        '【재화 획득: 암초 조각 ×2】 얕은 바다 어종을 모아 암초 조각으로 가공합니다.': '【获得货币：暗礁碎块 ×2】收集浅海鱼种，加工成暗礁碎块。',
        '【재화 획득: 심해의 파편 ×1】 조류 장어로 봉인되지 않은 무작위 추가 옵션 1줄의 종류와 수치를 교체하는 심해의 파편을 만듭니다.': '【获得货币：深海碎片 ×1】用潮流鳗制作深海碎片，可替换随机一条未封印额外词缀的类型与数值。',
        '【재화 획득: 심해의 파편 ×2】 발광 송어로 봉인되지 않은 무작위 추가 옵션 1줄의 종류와 수치를 교체하는 심해의 파편을 정제합니다.': '【获得货币：深海碎片 ×2】用发光鳟鱼精炼深海碎片，可替换随机一条未封印额外词缀的类型与数值。',
        '【장비 강화: 계열 재굴림 1줄】 발광 송어를 바쳐 원하는 계열의 기존 옵션 한 줄만 다시 굴립니다(다른 줄 보존, 등급 보정 없음).': '【装备强化：系列重掷1条】献上发光鳟鱼，仅重掷所选系列的一条现有词缀（其他词缀保留，无阶级修正）。',
        '【장비 강화: 확정 옵션 부여】 심연 등불고기를 제물로 바쳐 장비에 옵션 한 줄을 확정으로 부여합니다.': '【装备强化：确定赋予词缀】献祭深渊灯笼鱼，为装备确定赋予一条词缀。',
        '【재화 획득: 무작위 제작 재화 ×1】 조류 장어와 은빛 비늘치 더미에서 흘러나온 마력을 정제해 무작위 제작 재화 1개를 얻습니다.': '【获得货币：随机制作货币 ×1】精炼从潮流鳗与银鳞鱼堆中流出的魔力，获得1个随机制作货币。',
        '【재화 획득: 무작위 제작 재화 ×1】 발광 송어의 빛을 응축해 무작위 제작 재화 1개를 얻습니다.': '【获得货币：随机制作货币 ×1】凝聚发光鳟鱼的光，获得1个随机制作货币。',
        '【재화 획득: 무작위 제작 재화 ×2】 심연 등불고기와 발광 송어로 봉인된 보물함을 열어 무작위 제작 재화 2개를 얻습니다.': '【获得货币：随机制作货币 ×2】用深渊灯笼鱼与发光鳟鱼打开封印的宝箱，获得2个随机制作货币。',
        '【재화 획득: 무작위 제작 재화 ×2】 해류군주 비단잉어의 비늘로 만든 함에서 무작위 제작 재화 2개를 얻습니다.': '【获得货币：随机制作货币 ×2】从海流君主锦鲤鳞片制成的匣中获得2个随机制作货币。',
        '【재화 획득: 무작위 제작 재화 ×3】 리바이어던 본체와 무지갯빛 공포의 잔재로 채워진 최상급 보물함에서 무작위 제작 재화 3개를 얻습니다.': '【获得货币：随机制作货币 ×3】从装满利维坦本体与虹色恐怖残骸的顶级宝箱中获得3个随机制作货币。',
        '【장비 강화: 하락 없는 안전 재굴림】 발광 송어와 은빛 비늘치로 옵션 1줄을 다시 굴립니다. 결과가 기존보다 낮으면 적용되지 않고 원래 값이 유지됩니다.': '【装备强化：无下降的安全重掷】用发光鳟鱼与银鳞鱼重掷一条词缀。结果低于原值时不生效，保留原值。',
        '【장비 강화: 무작위 옵션 2줄 수치 재굴림】 심연 등불고기와 조류 장어로 무작위로 고른 옵션 두 줄의 수치만 같은 등급 안에서 다시 굴립니다(옵션 종류와 나머지 줄은 그대로).': '【装备强化：随机2条词缀数值重掷】用深渊灯笼鱼与潮流鳗，仅在同阶级内重掷随机选中的两条词缀的数值（词缀类型与其他词缀不变）。',
        '【장비 강화: 옵션 1줄 등급 +1 영구 재굴림】 심연 등불고기와 발광 송어로 무작위 옵션 1줄을 한 단계 높은 등급으로 다시 굴립니다(영구 적용).': '【装备强化：1条词缀阶级+1永久重掷】用深渊灯笼鱼与发光鳟鱼，将随机一条词缀以高一阶的阶级重掷（永久生效）。',
        '【장비 강화: 무작위 옵션 1줄을 원하는 계열로 변환】 발광 송어와 조류 장어로 무작위 옵션 한 줄을 선택한 계열의 옵션으로 바꿉니다.': '【装备强化：随机1条词缀转换为所选系列】用发光鳟鱼与潮流鳗，将随机一条词缀变为所选系列的词缀。',
        '【장비 강화: 최고 티어 옵션을 50% 효과로 메아리】 전설의 새끼 괴어와 심연 등불고기로 가장 높은 티어의 옵션 중 한 줄을 무작위로 골라, 나머지 옵션 중 무작위 한 줄을 그 옵션의 50% 효과로 덮어씁니다.': '【装备强化：以50%效果回响最高阶词缀】用传说幼怪鱼与深渊灯笼鱼，随机选取最高阶词缀中的一条，并将其余词缀中随机一条覆盖为该词缀的50%效果。',
        '【장비 강화: 옵션 1줄 영구 봉인】 해류군주 비단잉어와 발광 송어로 옵션 한 줄을 영구히 봉인합니다.': '【装备强化：永久封印1条词缀】用海流君主锦鲤与发光鳟鱼永久封印一条词缀。',
        '【장비 강화: 최상급 태그 옵션 확정(등급 +2)】 전설의 새끼 괴어와 심연 등불고기, 조류 장어로 최상급 태그 옵션을 확정 부여합니다.': '【装备强化：确定顶级标签词缀（阶级+2）】用传说幼怪鱼、深渊灯笼鱼与潮流鳗确定赋予顶级标签词缀。',
        '【장비 강화: 계열 재굴림(등급 +1)】 해류군주 비단잉어와 발광 송어로 원하는 계열의 기존 옵션만 다시 굴립니다(다른 줄 보존).': '【装备强化：系列重掷（阶级+1）】用海流君主锦鲤与发光鳟鱼，仅重掷所选系列的现有词缀（其他词缀保留）。',
        '【장비 강화: 심해 전용 고정 옵션 부착】 무지갯빛 공포와 해류군주 비단잉어, 심연 등불고기로 심해 전용 고정 옵션을 부착합니다(자리가 없으면 가장 낮은 줄을 바꿉니다).': '【装备强化：附加深海专属固定词缀】用虹色恐怖、海流君主锦鲤与深渊灯笼鱼附加深海专属固定词缀（无空位时替换最低的一条）。',
        '【장비 강화: 옵션 2줄 동시 영구 봉인 + 나머지 1줄 즉시 재단】 무지갯빛 공포와 발광 송어로 옵션 두 줄을 동시에 봉인하고, 남은 줄은 즉시 재단합니다.': '【装备强化：同时永久封印2条词缀 + 立即裁剪剩余1条】用虹色恐怖与发光鳟鱼同时封印两条词缀，并立即裁剪剩余的一条。',
        '【장비 강화: 강제 희귀 등급 승급】 무지갯빛 공포와 공허 리바이어던 새끼, 은빛 비늘치로 장비를 강제로 희귀 등급으로 승급시킵니다.': '【装备强化：强制升为稀有】用虹色恐怖、虚空利维坦幼崽与银鳞鱼将装备强制升至稀有品级。',
        '【장비 강화: 최상급 태그 옵션 확정(등급 +3) + 나쁜 옵션 1줄 무료 제거】 리바이어던 본체와 심연 등불고기로 최상급 태그 옵션을 확정 부여하며, 동시에 나쁜 줄 하나를 무료로 제거합니다.': '【装备强化：确定顶级标签词缀（阶级+3）+ 免费移除1条劣质词缀】用利维坦本体与深渊灯笼鱼确定赋予顶级标签词缀，同时免费移除一条劣质词缀。',
        '【장비 강화: 이 레시피 전용 최상위 고정 옵션 부착】 리바이어던 본체와 해류군주 비단잉어, 공허 리바이어던 새끼로 오직 이 레시피로만 얻는 최상위 고정 옵션을 부착합니다(자리가 없으면 가장 낮은 줄을 바꿉니다).': '【装备强化：附加本配方专属顶级固定词缀】用利维坦本体、海流君主锦鲤与虚空利维坦幼崽附加仅此配方可得的顶级固定词缀（无空位时替换最低的一条）。',
