        "레벨이 올라 스킬트리 포인트를 얻었습니다.\n‘스킬트리’에서 시작 지점과 이어진 노드를 골라 찍으세요.\n오른 능력치는 ‘캐릭터’에서 확인할 수 있습니다.": "升级获得了技能树点数。\n请在“技能树”中选择与起点相连的节点点亮。\n提升的属性可在“角色”中查看。",
        '첫 장비': '首件装备',
        "장비를 얻었습니다. 자동 장착이 켜져 있으면 빈 칸에 맞는 장비를 바로 착용합니다.\n‘장비’에서 착용한 장비의 효과를 확인하고, 보관 중인 장비와 비교하세요.\n바꿔 입으면 전투 화면의 생명 구슬 위에 DPS 변화가 뜹니다.": "获得了装备。开启自动装备时会立即穿戴适合空格的装备。\n请在“装备”中查看已穿戴装备的效果，并与仓库中的装备比较。\n更换后战斗画面生命球上方会显示DPS变化。",
        '무기와 스킬룬': '武器与技能符文',
        "스킬룬마다 쓸 수 있는 무기가 있습니다. 지금 무기로 쓸 수 없는 룬은 흐리게 보이고, 카드에 필요한 무기가 적혀 있습니다.\n장착한 룬을 쓸 수 없는 무기로 바꾸면 기본 공격으로 싸우다가, 맞는 무기를 들면 그 룬으로 돌아갑니다.": "每个技能符文都有可用的武器。当前武器无法使用的符文会显示为灰暗，卡牌上标有所需武器。\n若换成无法使用已装备符文的武器，则以基础攻击战斗，持有匹配武器后恢复使用该符文。",
