        "전투는 자동입니다. 캐릭터가 알아서 걷고 공격합니다.\n지금 할 일은 오른쪽 위 ‘목표’에 나옵니다.\n생명 구슬이 자주 비면 장비와 저항을 점검하세요.\n장비나 룬을 얻으면 그때마다 조작을 안내합니다.": "战斗为自动。角色会自行移动并攻击。\n当前要做的事显示在右上角的“目标”中。\n若生命球经常见底，请检查装备与抗性。\n每当获得装备或符文时都会说明操作。",
        "레벨 2가 되어 스킬트리 포인트를 얻었습니다.\n‘스킬트리’에서 시작 지점과 이어진 노드를 골라 찍으세요.": "达到2级，获得了技能树点数。\n请在“技能树”中选择与起点相连的节点点亮。",
        "장비나 제작 재화를 처음 얻었습니다.\n‘장비’에서 아이템을 눌러 지금 착용한 장비와 비교하고 착용하세요.": "首次获得了装备或制作货币。\n请在“装备”中点击物品，与当前穿戴的装备比较并穿戴。",
        '새 스킬룬': '新技能符文',
        "새 룬을 얻었습니다.\n‘스킬룬’에서 룬을 눌러 효과를 보고 공격 룬을 바꿔 보세요.": "获得了新符文。\n请在“技能符文”中点击符文查看效果，并尝试更换攻击符文。",
        '지도 개방': '地图开放',
        "다음 액트가 열렸습니다.\n‘지도’에서 지나온 액트로 돌아가 다시 사냥하거나, 마친 액트의 보상을 받을 수 있습니다.": "下一幕已开启。\n可在“地图”中返回已走过的幕重新狩猎，或领取已完成幕的奖励。",
