        '부적과 고급 수확 제작': '护身符与高级收获制作',
        '“미궁에서 건진 봉인편린에는 잘려 나간 옛 가지들의 원한이 서려 있어. 네 피를 먹여 깨우면 어떤 갑옷보다 든든한 부적이 되지. 그루터기 함의 식물로 하는 고급 수확 제작은 내가 가르쳐줄 수 있지. 조심해 독성이 강할 거야. 그만큼의 값도 받아야겠고.”': '“从迷宫捞出的封印碎片里，凝结着被砍下的旧枝的怨念。喂以你的血唤醒，就会成为比任何铠甲都可靠的护身符。用树桩匣的植物进行的高级收获制作，我可以教你。小心，毒性会很强。价钱也得相应地收。”',
        '다음: {act} 「{title}」': '下一个：{act}「{title}」',
        // ── 2026-11-05 v0.3.49 묶음(수확 제작, 배경음, 로그인 화면, 액트 보상 카드)의 글 ──
        '죽은 잔뿌리들이 겹겹이 엉켜 중정으로 오르는 길을 가로막은 지하 성소.': '层层枯死的细根纠缠在一起，挡住了通往中庭之路的地下圣所。',
        '아래쪽 뿌리의 수액을 빨아들여 영원을 유지하는 정원.': '吸取下方根系的树液来维持永恒的庭园。',
        '수액을 모두 빼앗긴 채 허공에 매달려 말라붙은 뿌리 숲.': '树液被夺尽，悬在虚空中干枯的根之森。',
        '하층의 수액을 중정으로 실어 나르는 황금 길의 교차로.': '将下层树液运往中庭的黄金之路交汇处。',
        '우물에서 건진 파편을 칼날로 담금질한 비밀 공방.': '将从井中捞起的碎片淬炼成刀刃的秘密工坊。',
        '수액 공급이 끊겨 시들어 버린 정원사의 마지막 보루.': '树液供给断绝而枯萎的园丁最后堡垒。',
        '수관에 모든 수액을 빼앗기고 속이 텅 비어버린 고목 도시.': '所有树液都被树冠夺走，内里空空如也的古木之城。',
        '기억에 없는 당신의 발자국이 바닥마다 포개어져 남은 회랑.': '每一层地面都叠留着你不记得的足迹的回廊。',
        '잘려 나간 가지들의 유해를 접붙여 마지막 고치를 품은 수관.': '嫁接被砍下枝条的遗骸，孕育着最后之茧的树冠。',
        '아홉 삽목의 울음이 하나의 왕관으로 맞물린 세계수의 끝.': '九株插枝的哭号咬合成一顶王冠的世界树尽头。',
