        '전투 전술': '战斗战术',
        '액트 3을 클리어하면 무료로 해금됩니다. 기본 공격 대상과 전투 거리를 정하고, 조건에 따라 행동하는 규칙을 만들 수 있습니다.': '通关第3幕后免费解锁。可设置默认攻击目标与战斗距离，并制定按条件执行的行动规则。',
