        '강화마다 공격 속도와 시전 속도 2% 증폭. 5강이면 룬 레벨 +1. 재료와 강화는 루프마다 초기화됩니다.': '每次强化使攻击速度与施法速度总增2%。强化至+5时，符文等级+1。材料与强化每次循环都会重置。',
        '창공의 탑에서 얻는 별도 재화입니다. 창공을 해금한 뒤 영구 강화에 사용할 수 있습니다. 보유량과 영구 룬 강화는 유지됩니다.': '这是在苍穹之塔获得的独立货币。解锁苍穹后可用于永久强化。持有数量与永久符文强化都会保留。',
        '각성 룬': '觉醒符文',
