        '그루터기 함 옵션': '树桩匣词缀',
        '고대 미궁의 봉인편린으로 부적을 풀고, 그루터기 함에 배치해 처치로 깨울 수 있습니다.': '可用古代迷宫的封印碎片解封护身符，再将其放入树桩匣，通过击杀敌人使其觉醒。',
